102	final class GraphBuilder {
103	    private final List<List<Edge>> adjacency;
104	
105	    private GraphBuilder(List<List<Edge>> adjacency) {
106	        this.adjacency = adjacency;
107	    }
108	
109	    static GraphBuilder withVertexCount(int vertexCount) {
110	        GraphChecks.validateVertexCount(vertexCount);
111	
112	        List<List<Edge>> adjacency = new ArrayList<>(vertexCount);
113	        for (int vertex = 0; vertex < vertexCount; vertex++) {
114	            adjacency.add(new ArrayList<>());
115	        }
116	        return new GraphBuilder(adjacency);
117	    }
118	
119	    GraphBuilder addUndirectedConnection(Connection connection) {
120	        validateConnection(connection);
121	        addDirectedEdgeUnchecked(connection.from, connection.to, connection.weight);
122	        addDirectedEdgeUnchecked(connection.to, connection.from, connection.weight);
123	        return this;
124	    }
125	
126	    GraphBuilder addDirectedConnection(Connection connection) {
127	        validateConnection(connection);
128	        addDirectedEdgeUnchecked(connection.from, connection.to, connection.weight);
129	        return this;
130	    }
131	
132	    Graph build() {
133	        return new Graph(copyAdjacency());
134	    }
135	
136	    private List<List<Edge>> copyAdjacency() {
137	        List<List<Edge>> adjacencyCopy = new ArrayList<>(adjacency.size());
138	        for (List<Edge> edges : adjacency) {
139	            adjacencyCopy.add(new ArrayList<>(edges));
140	        }
141	        return adjacencyCopy;
142	    }
143	
144	    private void addDirectedEdgeUnchecked(int from, int to, int weight) {
145	        adjacency.get(from).add(new Edge(to, weight));
146	    }
147	
148	    private void validateConnection(Connection connection) {
149	        if (connection == null) {
150	            throw new IllegalArgumentException("Connection must not be null");
151	        }
152	
153	        GraphChecks.validateVertex(connection.from, adjacency.size(), "from");
154	        GraphChecks.validateVertex(connection.to, adjacency.size(), "to");
155	        GraphChecks.validateWeight(connection.weight);
156	    }
157	}
