159	final class LegacyGraphAdapter {
160	    static final int DESTINATION_INDEX = 0;
161	    static final int WEIGHT_INDEX = 1;
162	    static final int EDGE_FIELD_COUNT = 2;
163	
164	    private LegacyGraphAdapter() {
165	    }
166	
167	    static void addUndirectedEdge(ArrayList<ArrayList<int[]>> adj, int u, int v, int weight) {
168	        validateAdjacencyList(adj);
169	        GraphChecks.validateVertex(u, adj.size(), "u");
170	        GraphChecks.validateVertex(v, adj.size(), "v");
171	        GraphChecks.validateWeight(weight);
172	
173	        adj.get(u).add(edge(v, weight));
174	        adj.get(v).add(edge(u, weight));
175	    }
176	
177	    static Graph toGraph(ArrayList<ArrayList<int[]>> adj) {
178	        validateAdjacencyList(adj);
179	
180	        GraphBuilder graph = GraphBuilder.withVertexCount(adj.size());
181	        for (int from = 0; from < adj.size(); from++) {
182	            ArrayList<int[]> rawEdges = requireNeighborList(adj, from);
183	            for (int[] rawEdge : rawEdges) {
184	                graph.addDirectedConnection(toConnection(from, rawEdge, adj.size()));
185	            }
186	        }
187	        return graph.build();
188	    }
189	
190	    static int[] edge(int destination, int weight) {
191	        return new int[]{destination, weight};
192	    }
193	
194	    private static Connection toConnection(int from, int[] rawEdge, int vertexCount) {
195	        validateRawEdge(rawEdge, from);
196	
197	        int to = rawEdge[DESTINATION_INDEX];
198	        int weight = rawEdge[WEIGHT_INDEX];
199	        GraphChecks.validateVertex(to, vertexCount, "neighbor");
200	        GraphChecks.validateWeight(weight);
201	        return Connection.of(from, to, weight);
202	    }
203	
204	    private static ArrayList<int[]> requireNeighborList(ArrayList<ArrayList<int[]>> adj, int vertex) {
205	        ArrayList<int[]> neighbors = adj.get(vertex);
206	        if (neighbors == null) {
207	            throw new IllegalArgumentException(
208	                    "Adjacency list contains a null neighbor list at vertex " + vertex);
209	        }
210	        return neighbors;
211	    }
212	
213	    private static void validateAdjacencyList(ArrayList<ArrayList<int[]>> adj) {
214	        if (adj == null) {
215	            throw new IllegalArgumentException("Adjacency list must not be null");
216	        }
217	    }
218	
219	    private static void validateRawEdge(int[] rawEdge, int fromVertex) {
220	        if (rawEdge == null || rawEdge.length < EDGE_FIELD_COUNT) {
221	            throw new IllegalArgumentException(
222	                    "Edge at vertex " + fromVertex + " must contain destination and weight");
223	        }
224	    }
225	}
