237	final class Distances {
238	    private static final int UNREACHABLE = Integer.MAX_VALUE;
239	
240	    private final int[] values;
241	
242	    private Distances(int[] values) {
243	        this.values = values;
244	    }
245	
246	    static Distances forSource(int vertexCount, int source) {
247	        int[] values = new int[vertexCount];
248	        Arrays.fill(values, UNREACHABLE);
249	        values[source] = 0;
250	        return new Distances(values);
251	    }
252	
253	    boolean isStale(QueueEntry entry) {
254	        return entry.distance != values[entry.vertex];
255	    }
256	
257	    boolean tryUpdate(int vertex, int nextDistance) {
258	        if (nextDistance >= values[vertex]) {
259	            return false;
260	        }
261	
262	        values[vertex] = nextDistance;
263	        return true;
264	    }
265	
266	    ArrayList<Integer> toList() {
267	        ArrayList<Integer> result = new ArrayList<>(values.length);
268	        for (int distance : values) {
269	            result.add(distance);
270	        }
271	        return result;
272	    }
273	}
