275	final class ShortestPathSolver {
276	    private final Graph graph;
277	    private final Distances distances;
278	    private final PriorityQueue<QueueEntry> minHeap;
279	
280	    private ShortestPathSolver(Graph graph, int source) {
281	        this.graph = graph;
282	        this.distances = Distances.forSource(graph.vertexCount(), source);
283	        this.minHeap = new PriorityQueue<>(Comparator.comparingInt(entry -> entry.distance));
284	        minHeap.offer(new QueueEntry(0, source));
285	    }
286	
287	    static Distances solve(Graph graph, int source) {
288	        return new ShortestPathSolver(graph, source).run();
289	    }
290	
291	    private Distances run() {
292	        while (!minHeap.isEmpty()) {
293	            QueueEntry current = minHeap.poll();
294	            if (distances.isStale(current)) {
295	                continue;
296	            }
297	
298	            relaxNeighborsOf(current);
299	        }
300	        return distances;
301	    }
302	
303	    private void relaxNeighborsOf(QueueEntry current) {
304	        for (Edge edge : graph.neighborsOf(current.vertex)) {
305	            tryRelax(current, edge);
306	        }
307	    }
308	
309	    private void tryRelax(QueueEntry current, Edge edge) {
310	        int nextDistance = GraphChecks.addDistances(current.distance, edge.weight);
311	        if (distances.tryUpdate(edge.to, nextDistance)) {
312	            minHeap.offer(new QueueEntry(nextDistance, edge.to));
313	        }
314	    }
315	}
