317	final class GraphChecks {
318	    private GraphChecks() {
319	    }
320	
321	    static void validateVertexCount(int vertexCount) {
322	        if (vertexCount < 0) {
323	            throw new IllegalArgumentException("Vertex count must be non-negative");
324	        }
325	    }
326	
327	    static void validateVertex(int vertex, int vertexCount, String label) {
328	        if (vertex < 0 || vertex >= vertexCount) {
329	            throw new IllegalArgumentException(label + " vertex out of range: " + vertex);
330	        }
331	    }
332	
333	    static void validateWeight(int weight) {
334	        if (weight < 0) {
335	            throw new IllegalArgumentException("Dijkstra's algorithm requires non-negative edge weights");
336	        }
337	    }
338	
339	    static int addDistances(int left, int right) {
340	        long sum = (long) left + right;
341	        if (sum > Integer.MAX_VALUE) {
342	            throw new ArithmeticException("Shortest path exceeds supported integer range");
343	        }
344	        return (int) sum;
345	    }
346	}
